-- Initial schema for MusicStore.Api on PostgreSQL.
-- Run as musicstore_migrator (or as postgres after SET ROLE musicstore_migrator).

SET ROLE musicstore_migrator;

REVOKE CREATE ON SCHEMA public FROM PUBLIC;

CREATE TABLE IF NOT EXISTS "Compositions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title" text NOT NULL,
    "DurationSeconds" integer NOT NULL,
    "PerformerType" text NOT NULL,
    "PerformerId" integer NOT NULL
);

CREATE TABLE IF NOT EXISTS "Ensembles" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" text NOT NULL,
    "Genre" text,
    "FoundedYear" integer
);

CREATE TABLE IF NOT EXISTS "Musicians" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" text NOT NULL,
    "Country" text,
    "BirthDate" date
);

CREATE TABLE IF NOT EXISTS "Users" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Username" text NOT NULL,
    "PasswordHash" text NOT NULL,
    "Role" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Users_Username"
    ON "Users" ("Username");

CREATE TABLE IF NOT EXISTS "Discs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title" text NOT NULL,
    "ImageUrl" text NOT NULL,
    "Price" numeric(10, 2) NOT NULL,
    "Quantity" integer NOT NULL,
    "MusicianId" integer NOT NULL,
    "CompositionId" integer NOT NULL,
    CONSTRAINT "FK_Discs_Musicians_MusicianId"
        FOREIGN KEY ("MusicianId") REFERENCES "Musicians" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Discs_Compositions_CompositionId"
        FOREIGN KEY ("CompositionId") REFERENCES "Compositions" ("Id") ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS "IX_Discs_MusicianId"
    ON "Discs" ("MusicianId");
CREATE INDEX IF NOT EXISTS "IX_Discs_CompositionId"
    ON "Discs" ("CompositionId");

CREATE TABLE IF NOT EXISTS "Sales" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DiscId" integer NOT NULL,
    "UserId" integer NOT NULL,
    "Quantity" integer NOT NULL,
    "TotalAmount" numeric(10, 2) NOT NULL,
    "SaleDate" timestamp with time zone NOT NULL,
    CONSTRAINT "FK_Sales_Discs_DiscId"
        FOREIGN KEY ("DiscId") REFERENCES "Discs" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Sales_Users_UserId"
        FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS "IX_Sales_DiscId"
    ON "Sales" ("DiscId");
CREATE INDEX IF NOT EXISTS "IX_Sales_UserId"
    ON "Sales" ("UserId");
